ICON='<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M5 12h14M13 6l6 6-6 6"/></svg>'
def render(k):
    L=D[k]
    nav="".join(f'<a href="#{i}-{k}">{n}</a>' for i,n in L["nav"])
    tr="".join(f'<article class="trk"><span class="tag">{t}</span><h3>{n}</h3><p>{d}</p><div class="proj"><small>{L["lbl_proj"]}</small><b>{pr}</b></div></article>' for t,n,d,pr in L["tracks"])
    so="".join(f'<article class="sol"><h3>{n}</h3><p>{d}</p><div class="proj"><small>{L["lbl_del"]}</small><b>{r}</b></div></article>' for n,d,r in L["sols"])
    st="".join(f'<li><span class="num">{i}</span><div><h3>{n}</h3><p>{d}</p></div></li>' for i,(n,d) in enumerate(L["steps"],1))
    fq="".join(f'<details><summary>{q}</summary><p>{a}</p></details>' for q,a in L["faq"])
    op="".join(f"<option>{o}</option>" for o in L["f_t"])
    code=f'<span class="cm">// {L["ed_file"]}</span>\n<span class="kw">const</span> app = <span class="fn">build</span>(idea, skills);\n<span class="kw">await</span> app.<span class="fn">test</span>();\n<span class="kw">await</span> app.<span class="fn">deploy</span>(<span class="st">"production"</span>);'
    return f'''<div class="lang" data-l="{k}" dir="{L["dir"]}" lang="{k}"{"" if k=="ar" else " hidden"}>
<header class="top"><div class="wrap bar"><a class="brand" href="#top-{k}"><i>د</i><b>{L["name"]}</b></a><nav>{nav}</nav><div class="bar-r"><button class="sw" data-go="{L["oth_k"]}" type="button">{L["oth"]}</button><a class="btn pri sm" href="#contact-{k}">{L["cta"]}</a></div></div></header>
<main id="top-{k}">
<section class="hero"><div class="wrap hg"><div><p class="eyebrow">{L["eyebrow"]}</p><h1>{L["h1"]}</h1><p class="lead">{L["sub"]}</p><div class="cta"><a class="btn pri" href="#academy-{k}">{L["b1"]}</a><a class="btn out" href="#solutions-{k}">{L["b2"]}</a></div></div>
<div class="edwrap"><div class="ed"><div class="edbar"><i></i><i></i><i></i><span>{L["ed_file"]}</span></div><pre>{code}</pre></div><div class="pill ok"><span></span>{L["ed_ok"]}</div><div class="pill note">{L["ed_note"]}</div></div></div></section>
<section class="path"><div class="wrap"><h2>{L["path_h"]}</h2><div class="tabs" role="tablist"><button role="tab" class="on" data-t="a">{L["path_a"]}</button><button role="tab" data-t="s">{L["path_s"]}</button></div>
<div class="panel" data-p="a"><div><h3>{L["pa_t"]}</h3><p>{L["pa_p"]}</p></div><a class="btn pri" href="#academy-{k}">{L["b1"]}{ICON}</a></div>
<div class="panel" data-p="s" hidden><div><h3>{L["ps_t"]}</h3><p>{L["ps_p"]}</p></div><a class="btn pri" href="#solutions-{k}">{L["b2"]}{ICON}</a></div></div></section>
<section id="academy-{k}" class="sec"><div class="wrap"><div class="sh"><p class="eyebrow">{L["ac_eye"]}</p><h2>{L["ac_h"]}</h2><p>{L["ac_p"]}</p></div><div class="g3">{tr}</div></div></section>
<section id="solutions-{k}" class="sec sand"><div class="wrap"><div class="sh"><p class="eyebrow">{L["so_eye"]}</p><h2>{L["so_h"]}</h2><p>{L["so_p"]}</p></div><div class="g3">{so}</div></div></section>
<section id="method-{k}" class="sec"><div class="wrap"><div class="sh"><p class="eyebrow">{L["me_eye"]}</p><h2>{L["me_h"]}</h2></div><ol class="steps">{st}</ol></div></section>
<section id="faq-{k}" class="sec" style="padding-top:0"><div class="wrap narrow"><h2>{L["faq_h"]}</h2>{fq}</div></section>
<section id="contact-{k}" class="sec"><div class="wrap"><div class="band"><div><h2>{L["con_h"]}</h2><p>{L["con_p"]}</p></div>
<form data-k="{k}"><label>{L["f_n"]}<input id="n-{k}" required></label><label>{L["f_e"]}<input id="e-{k}" type="email" required></label><label><select id="t-{k}">{op}</select></label><label>{L["f_m"]}<textarea id="m-{k}" rows="3"></textarea></label><button class="btn pri" type="submit">{L["f_s"]}</button><p class="demo" hidden>{L["f_demo"]}</p></form></div></div></section>
</main><footer><div class="wrap fg"><a class="brand" href="#top-{k}"><i>د</i><b>{L["name"]}</b></a><p>{L["foot"]}</p><small>© 2026 {L["name"]}. {L["rights"]}</small></div></footer></div>'''
CSS='''
/* layout: pale-cool ground, ultramarine primary, sand panels; Readex Pro display, Plex body; editor mockup hero */
:root{--bg:#F6F8FB;--paper:#FFFFFF;--ink:#0E1726;--mut:#52607A;--line:#DDE3EE;--pri:#2548F5;--pri-d:#1A36C4;--pri-t:#E7ECFF;--sand:#F3EBDD;--ok:#0E9F6E;--r:18px;--max:1160px;color-scheme:light}
*{box-sizing:border-box;margin:0;padding:0}html{scroll-behavior:smooth}
body{background:var(--bg);color:var(--ink);font:400 17px/1.75 'IBM Plex Sans Arabic','Readex Pro',system-ui,sans-serif;-webkit-font-smoothing:antialiased;padding-left:0;padding-right:0}
.lang[lang=en]{font-family:'Readex Pro','IBM Plex Sans Arabic',system-ui,sans-serif}
h1,h2,h3,.brand b,.btn,.eyebrow,.num{font-family:'Readex Pro','IBM Plex Sans Arabic',system-ui,sans-serif}
h1,h2,h3{text-wrap:balance}a{color:inherit;text-decoration:none}
.wrap{max-width:var(--max);margin:0 auto;padding-left:max(16px,env(safe-area-inset-left,0px));padding-right:max(16px,env(safe-area-inset-right,0px))}
.wrap.narrow{max-width:820px}
body::before{content:"";position:fixed;inset:0 0 auto;height:env(safe-area-inset-top,0px);background:var(--paper);z-index:60}
.top{position:sticky;top:env(safe-area-inset-top,0px);z-index:50;background:#fffffff2;backdrop-filter:blur(10px);border-bottom:1px solid var(--line)}
.bar{display:flex;align-items:center;justify-content:space-between;gap:18px;height:72px}
.brand{display:flex;align-items:center;gap:10px}.brand i{width:38px;height:38px;border-radius:11px;background:var(--pri);color:#fff;font:700 22px/38px 'Readex Pro',sans-serif;text-align:center;font-style:normal}
.brand b{font-size:22px;font-weight:700;letter-spacing:-.01em}
nav{display:flex;gap:26px;font-weight:500;font-size:15.5px;color:var(--mut)}nav a:hover{color:var(--pri)}
.bar-r{display:flex;gap:10px;align-items:center}
.sw{font:600 14px 'Readex Pro',sans-serif;background:none;border:1px solid var(--line);border-radius:30px;padding:7px 15px;cursor:pointer;color:var(--ink)}.sw:hover{border-color:var(--pri);color:var(--pri)}
.btn{display:inline-flex;align-items:center;justify-content:center;gap:8px;font-weight:600;font-size:16px;padding:14px 26px;border-radius:12px;border:1.5px solid transparent;cursor:pointer;transition:.18s}
.btn svg{width:18px;height:18px;stroke:currentColor;fill:none;stroke-width:2;stroke-linecap:round;stroke-linejoin:round}[dir=rtl] .btn svg{transform:scaleX(-1)}
.btn.pri{background:var(--pri);color:#fff}.btn.pri:hover{background:var(--pri-d);transform:translateY(-1px)}
.btn.out{border-color:var(--line);background:var(--paper)}.btn.out:hover{border-color:var(--pri);color:var(--pri)}.btn.sm{padding:9px 18px;font-size:14.5px}
:focus-visible{outline:3px solid #F5A623;outline-offset:2px}
.hero{padding:76px 0 70px;background:linear-gradient(180deg,var(--paper),var(--bg))}
.hg{display:grid;grid-template-columns:1.05fr .95fr;gap:56px;align-items:center}
.eyebrow{font-weight:600;font-size:14px;color:var(--pri);letter-spacing:.04em;margin-bottom:14px}
h1{font-size:clamp(36px,5.2vw,62px);line-height:1.2;font-weight:700;letter-spacing:-.02em}h1 span{color:var(--pri)}
.lead{font-size:19px;color:var(--mut);margin-top:22px;max-width:560px}.cta{display:flex;gap:12px;flex-wrap:wrap;margin-top:32px}
.edwrap{position:relative;min-width:0}.ed{background:#0E1726;border-radius:var(--r);box-shadow:0 30px 60px -20px #1a2a6c44,0 0 0 1px #0e172610;overflow:hidden}
.edbar{display:flex;align-items:center;gap:7px;padding:13px 16px;background:#16213a;direction:ltr}.edbar i{width:10px;height:10px;border-radius:50%;background:#44527a}.edbar span{margin-inline-start:12px;font:12.5px 'JetBrains Mono',monospace;color:#8c9bc0}
.ed pre{padding:24px 22px 30px;font:15.5px/1.95 'JetBrains Mono',ui-monospace,monospace;color:#b8c4e4;direction:ltr;text-align:left;overflow-x:auto}
.kw{color:#8EA6FF}.fn{color:#7FE0C0}.st{color:#FFC978}.cm{color:#61719b}
.pill{position:absolute;background:var(--paper);border:1px solid var(--line);border-radius:30px;padding:9px 18px;font:600 14px 'Readex Pro',sans-serif;box-shadow:0 10px 24px #0e172614;display:flex;gap:9px;align-items:center}
.pill.ok{inset-inline-end:-10px;bottom:-22px}.pill.ok span{width:9px;height:9px;border-radius:50%;background:var(--ok);box-shadow:0 0 0 4px #0e9f6e22}.pill.note{inset-inline-start:-14px;top:-18px;color:var(--pri)}
.path{padding:10px 0 20px}.path .wrap{background:var(--paper);border:1px solid var(--line);border-radius:26px;padding:34px;max-width:calc(var(--max) - 0px)}
.path h2{font-size:24px;margin-bottom:18px}
.tabs{display:inline-flex;background:var(--bg);border-radius:14px;padding:5px;gap:4px;margin-bottom:22px;max-width:100%;flex-wrap:wrap}
.tabs button{font:600 15px 'Readex Pro',sans-serif;border:0;background:none;padding:10px 20px;border-radius:10px;cursor:pointer;color:var(--mut)}.tabs button.on{background:var(--paper);color:var(--pri);box-shadow:0 2px 8px #0e172614}
.panel{display:flex;justify-content:space-between;align-items:center;gap:24px;flex-wrap:wrap}.panel[hidden]{display:none}.panel h3{font-size:23px;margin-bottom:6px}.panel p{color:var(--mut);max-width:620px}
.sec{padding:96px 0}.sand{background:var(--sand)}
.sh{max-width:700px;margin-bottom:48px}h2{font-size:clamp(28px,3.6vw,42px);line-height:1.28;font-weight:700;letter-spacing:-.015em}.sh p:last-child{color:var(--mut);margin-top:12px;font-size:18px}
.g3{display:grid;grid-template-columns:repeat(3,1fr);gap:20px}
.trk,.sol{background:var(--paper);border:1px solid var(--line);border-radius:var(--r);padding:28px;display:flex;flex-direction:column;gap:10px;min-width:0;transition:.2s}
.trk:hover,.sol:hover{border-color:var(--pri);transform:translateY(-3px);box-shadow:0 16px 34px -14px #2548f544}
.tag{align-self:flex-start;font:600 13px 'Readex Pro',sans-serif;background:var(--pri-t);color:var(--pri);padding:4px 13px;border-radius:30px}
.trk h3,.sol h3{font-size:21px;line-height:1.35}.trk p,.sol p{color:var(--mut);font-size:16px}
.proj{margin-top:auto;padding-top:16px;border-top:1px dashed var(--line);display:flex;flex-direction:column}.proj small{color:var(--mut);font-size:13px}.proj b{font-weight:600}
.sand .sol{border-color:#e6dbc5}
.steps{list-style:none;display:grid;grid-template-columns:repeat(5,1fr);gap:22px;counter-reset:x}
.steps li{display:flex;flex-direction:column;gap:14px;min-width:0;position:relative}
.num{width:46px;height:46px;border-radius:50%;background:var(--pri);color:#fff;display:grid;place-items:center;font-weight:700}
.steps h3{font-size:20px;margin-bottom:4px}.steps p{color:var(--mut);font-size:15.5px}
details{background:var(--paper);border:1px solid var(--line);border-radius:14px;padding:4px 22px;margin-top:12px}
summary{cursor:pointer;font:600 17px 'Readex Pro','IBM Plex Sans Arabic',sans-serif;padding:16px 0;list-style:none;display:flex;justify-content:space-between;gap:16px}
summary::-webkit-details-marker{display:none}summary::after{content:"+";color:var(--pri);font-size:24px;line-height:1}details[open] summary::after{content:"–"}
details p{color:var(--mut);padding:0 0 18px}
.band{background:var(--pri);color:#fff;border-radius:30px;padding:56px;display:grid;grid-template-columns:1fr 1fr;gap:44px;align-items:center}
.band p{color:#dbe3ff;margin-top:12px;font-size:18px}
form{display:grid;gap:10px}label{display:block;font-size:14px;color:#dbe3ff}
input,select,textarea{font:inherit;width:100%;margin-top:5px;padding:13px 16px;border-radius:11px;border:1.5px solid transparent;background:#fff;color:var(--ink)}select{margin-top:0}
form .btn.pri{background:#0E1726;color:#fff;margin-top:6px}form .btn.pri:hover{background:#000}
.demo{background:#ffffff22;border-radius:11px;padding:12px 16px;font-size:15px;color:#fff!important;margin:0!important}.demo[hidden]{display:none}
footer{padding:44px 0 36px;border-top:1px solid var(--line);background:var(--paper)}.fg{display:flex;align-items:center;justify-content:space-between;gap:20px;flex-wrap:wrap}.fg p{color:var(--mut)}.fg small{color:var(--mut)}
@media(max-width:980px){.hg,.band{grid-template-columns:1fr}.g3{grid-template-columns:1fr 1fr}.steps{grid-template-columns:1fr 1fr}.sec{padding:68px 0}.hero{padding:48px 0 54px}nav{display:none}.band{padding:34px 24px}.path .wrap{padding:24px}}
@media(max-width:600px){.g3,.steps{grid-template-columns:1fr}body{font-size:16px}.bar .btn{display:none}.pill.ok{inset-inline-end:8px}.pill.note{inset-inline-start:8px}.ed pre{font-size:13px}}
@media(prefers-reduced-motion:reduce){html{scroll-behavior:auto}.btn,.trk,.sol{transition:none}}
'''
html=f'''<title>Deraya Studio</title>
<meta name="claude:viewport-fit-sides" content="cover">
<link rel="preconnect" href="https://fonts.googleapis.com"><link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
<link href="https://fonts.googleapis.com/css2?family=IBM+Plex+Sans+Arabic:wght@400;500;600&family=Readex+Pro:wght@400;500;600;700&family=JetBrains+Mono:wght@400;500&display=swap" rel="stylesheet">
<style>{CSS}</style>
{render("ar")}{render("en")}
<script>
document.querySelectorAll('[data-go]').forEach(function(b){{b.addEventListener('click',function(){{var t=b.getAttribute('data-go');document.querySelectorAll('[data-l]').forEach(function(d){{d.hidden=d.getAttribute('data-l')!==t}});window.scrollTo(0,0)}})}});
document.querySelectorAll('.tabs').forEach(function(t){{t.querySelectorAll('button').forEach(function(b){{b.addEventListener('click',function(){{var root=t.parentNode;t.querySelectorAll('button').forEach(function(x){{x.classList.toggle('on',x===b)}});root.querySelectorAll('.panel').forEach(function(p){{p.hidden=p.getAttribute('data-p')!==b.getAttribute('data-t')}})}})}})}});
document.querySelectorAll('form[data-k]').forEach(function(f){{f.addEventListener('submit',function(e){{e.preventDefault();f.querySelector('.demo').hidden=false}})}});
</script>'''
open("pro.html","w").write(html);print(len(html))
